  // cancel unknown rejected
  { stock: {}, events: [{ type: "cancel", id: "x" }] },
  // expire reserved
  { stock: { a: 5 }, events: [{ type: "order", id: "o1", item: "a", qty: 1 }, { type: "expire", id: "o1" }] },
