  { stock: { a: 2 }, events: [
    { type: "order", id: "o1", item: "a", qty: 3 },
    { type: "order", id: "o2", item: "a", qty: 4 },
    { type: "restock", item: "a", qty: 10 },
  ]},
  // bad ids
  { stock: {}, events: [{ type: "order", item: "a", qty: 1 }] },
  { stock: {}, events: [{ type: "order", id: "", item: "a", qty: 1 }] },
  { stock: {}, events: [{ type: "order", id: "o", qty: 1 }] },
  { stock: {}, events: [{ type: "order", id: "o", item: "", qty: 1 }] },
  { stock: {}, events: [{ type: "order", id: "o", item: "a" }] },
  { stock: {}, events: [{ type: "order", id: "o", item: "a", qty: 0 }] },
  { stock: {}, events: [{ type: "order", id: "o", item: "a", qty: -2 }] },
  // duplicate order
  { stock: { a: 5 }, events: [{ type: "order", id: "o", item: "a", qty: 1 }, { type: "order", id: "o", item: "a", qty: 1 }] },
  // malformed event
  { stock: {}, events: [{ type: "order", id: "o", item: "a", qty: 1 }, null] },
  // bad type
  { stock: {}, events: [{ type: "weird" }] },
  // ship invalid qty
  { stock: { a: 5 }, events: [{ type: "order", id: "o", item: "a", qty: 1 }, { type: "ship", id: "o", qty: 0 }] },
  // restock invalid qty
  { stock: {}, events: [{ type: "restock", item: "a", qty: 0 }] },
  // complex chain: cancel freeing queue to fulfill
  { stock: { a: 5, b: 5 }, events: [
    { type: "order", id: "o1", item: "a", qty: 5 },
    { type: "order", id: "o2", item: "a", qty: 3 },
    { type: "cancel", id: "o1" },
    { type: "order", id: "o3", item: "b", qty: 2 },
  ]},
  // expire freeing
  { stock: { a: 2 }, events: [
    { type: "order", id: "o1", item: "a", qty: 2 },
    { type: "order", id: "o2", item: "a", qty: 1 },
    { type: "expire", id: "o1" },
  ]},
  // many mix
  { stock: { a: 10, b: 10 }, events: [
    { type: "order", id: "o1", item: "a", qty: 4 },
    { type: "order", id: "o2", item: "b", qty: 30 },
    { type: "ship", id: "o1", qty: 2 },
    { type: "restock", item: "b", qty: 25 },
    { type: "order", id: "o3", item: "a", qty: 5 },
    { type: "cancel", id: "o2" },
