  // repeated restock
  { stock: {}, events: [
    { type: "restock", item: "a", qty: 3 },
    { type: "order", id: "o1", item: "a", qty: 5 },
    { type: "restock", item: "a", qty: 3 },
  ]},
  // empty events
  { stock: { a: 1 }, events: [] },
  // empty stock
  { stock: {}, events: [{ type: "order", id: "o1", item: "a", qty: 1 }] },
